import os
import json

from typing import Any

from taf.rfrl.l3_call.cell.cell_factory import CellFactory
from taf.rfrl.l3_call.pcap.exceptions import InvalidFileStructureError, \
    UnexpectedMessageFound, \
    ExpectedMessageNotFound, \
    AttachMsgsFoundInPcap, \
    UnexpectedNumberOfAttachMsgs
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output
from taf.rfrl.l3_call.pcap.nok_message_details import NOK_MESSAGE_DETAILS
from robot.libraries.BuiltIn import BuiltIn


class VerifyPcap:
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self, ran, cell_distname):
        self._cell_distname = cell_distname
        self._ran = ran
        self._cell = CellFactory.create_cell(ran=self._ran, cell_distname=self._cell_distname,
                                             bts_connection_alias=f"l3_call_{self._get_bts_node()}")
        self._protocol = self._cell.get_protocol_for_pcap_verification()
        self._ok_msgs = self._cell.get_ok_msgs_and_procedure_codes()
        if 'NRCELL' in cell_distname:
            self._nok_msgs = {}
            self._nok_structures = self._cell.get_nok_structures()
        else:
            self._nok_msgs = self._cell.get_nok_msgs_and_procedure_codes()
            self._nok_structures = []

    def verify_pcap_file(self, pcap_path, attach_should_be_possible):
        """
        Verifies content of pcap file after L3 Call procedure.
        :param pcap_path: path to pcap file (local)
        :type pcap_path: str
        :param attach_should_be_possible: is attach expected to succeed
        :type attach_should_be_possible: bool
        """
        self._verify_pcap_file(pcap_path, attach_should_be_possible)

    def verify_pcap_file_after_parallel_call(self, pcap_path, number_of_expected_attach_msgs):
        """
        Verifies content of pcap file after Parallel L3 Call procedure by checking if
        number of each attach msgs equals number_of_expected_attach_msgs.
        :param pcap_path: path to pcap file (local)
        :type pcap_path: str
        :param number_of_expected_attach_msgs: expected number of attach messages
        :type number_of_expected_attach_msgs: int
        """
        self._verify_pcap_file_after_parallel_call(pcap_path=pcap_path,
                                                   number_of_expected_attach_msgs=number_of_expected_attach_msgs)

    def _verify_pcap_file(self, pcap_path, attach_should_be_possible):
        all_msg_names, all_msg_structures = self._get_msg_names_and_structures_from_pcap(path_to_pcap=pcap_path)

        if attach_should_be_possible:
            self._check_msg_presence_in_pcap(all_msg_names=all_msg_names,
                                             all_msg_structures=all_msg_structures)

        if not attach_should_be_possible:
            all_msg_names = self._remove_warning_messages(all_msg_names=all_msg_names)
            if all_msg_names:
                raise AttachMsgsFoundInPcap(
                    "Attach msgs found in pcap, seems like attach was possible! "
                    "Check your pcap at {}".format(pcap_path))

    @log_input_and_output
    def _remove_warning_messages(self, all_msg_names):
        warining_msgs = ["WriteReplaceWarningRequest", "ErrorIndication"]
        return [msg_name for msg_name in all_msg_names if msg_name not in warining_msgs]

    def _verify_pcap_file_after_parallel_call(self, pcap_path, number_of_expected_attach_msgs):
        all_msg_names, all_msg_structures = self._get_msg_names_and_structures_from_pcap(path_to_pcap=pcap_path)

        self._check_if_unexpected_msgs_are_present_in_pcap_after_parallel_call(all_msg_names=all_msg_names,
                                                                               all_msg_structures=all_msg_structures)
        self._check_if_number_of_attach_msgs_after_parallel_call_is_correct(
            all_msgs_names=all_msg_names,
            number_of_expected_attach_msgs=number_of_expected_attach_msgs)

    def _get_msg_names_and_structures_from_pcap(self, path_to_pcap):
        path_to_json = path_to_pcap.split(".")[0] + ".json"
        os.system(
            "tshark -2 -R '{}.procedureCode' -r {} -T json >{}".format(self._protocol, path_to_pcap, path_to_json))

        return self._parse_msg_names_and_structures(path_to_json=path_to_json)

    def _parse_msg_names_and_structures(self, path_to_json):
        with open(path_to_json, "r") as json_file:
            json_content = json.load(json_file)

        msg_structures = []
        msg_names = []
        for msg in json_content:
            try:
                entry_point = msg["_source"]["layers"][self._protocol]
                msg_structures.append(entry_point)
                msg_names.append(self._get_msg_name_from_entry_point(entry_point))

            except KeyError:
                raise InvalidFileStructureError(
                    'PCAP file structure might have changed, please check content of {} file'.format(path_to_json))
        return msg_names, msg_structures

    def _get_msg_name_from_entry_point(self, dict_of_values):
        for key, val in dict_of_values.items():
            value_element = "{}.value_element".format(self._protocol)
            if key == value_element:
                msg_name = list(val.keys())[0].split(".")[-1].split("_")[0]
                return msg_name

            if isinstance(val, dict):
                item = self._get_msg_name_from_entry_point(val)

                if item is not None:
                    return item

    def _count_msgs_occurrence_in_pcap_after_parallel_call(self, all_msg_names):
        msgs_occurrence = {}
        for ok_msg, ok_msg_id in self._ok_msgs.items():
            msgs_occurrence[ok_msg] = all_msg_names.count(ok_msg)

        return msgs_occurrence

    def _check_if_unexpected_msgs_are_present_in_pcap_after_parallel_call(self, all_msg_names, all_msg_structures):
        for msg, msg_id in self._nok_msgs.items():
            if msg in all_msg_names:
                raise UnexpectedMessageFound('{} message should not be in the PCAP log.'.format(msg))

        for nok_structure in self._nok_structures:
            if not self._validate_nok_structure_not_present(pcap_data=all_msg_structures,
                                                            nok_structure=nok_structure):
                raise UnexpectedMessageFound("Message structure that should not be in the PCAP log was found. "
                                             "Structure details: {}".format(json.dumps(nok_structure, indent=4)))

    def _check_if_number_of_attach_msgs_after_parallel_call_is_correct(self, all_msgs_names,
                                                                       number_of_expected_attach_msgs):
        msgs_count = self._count_msgs_occurrence_in_pcap_after_parallel_call(all_msg_names=all_msgs_names)
        for msg, count in msgs_count.items():
            if count != number_of_expected_attach_msgs:
                raise UnexpectedNumberOfAttachMsgs("Number of {0} msgs is different than expected! "
                                                   "Expected number of attach msgs: {1}, number of occurrences:"
                                                   " {2}".format(msg, number_of_expected_attach_msgs, count))

    def _check_msg_presence_in_pcap(self, all_msg_names, all_msg_structures):
        for msg_name, msg_id in self._ok_msgs.items():
            if msg_name not in all_msg_names:
                raise ExpectedMessageNotFound("{} message is not in the PCAP log.".format(msg_name))

        for msg_name, msg_id in self._nok_msgs.items():
            if msg_name in all_msg_names:
                raise UnexpectedMessageFound("{} message should not be in the PCAP log. {}".format(
                    msg_name, NOK_MESSAGE_DETAILS.get(msg_name, "")
                ))

        for nok_structure in self._nok_structures:
            if not self._validate_nok_structure_not_present(pcap_data=all_msg_structures,
                                                            nok_structure=nok_structure):
                raise UnexpectedMessageFound("Message structure that should not be in the PCAP log was found. "
                                             "Structure details: {}".format(json.dumps(nok_structure, indent=4)))

    def _validate_nok_structure_not_present(self, pcap_data: list[dict[str, Any]],
                                            nok_structure: dict[str, Any]) -> bool:
        """
        Validates that the NOK structure is not present in the pcap data.
        Returns True if NOK structure is NOT found, False otherwise.
        """
        for data_frame in pcap_data:
            if self._contains_structure_pattern(data_frame, nok_structure):
                return False
        return True

    def _contains_structure_pattern(self, data_frame: dict[str, Any], searched_structure: dict[str, Any]) -> bool:
        """
        Searches entire nested dictionary structure for searched_structure match.
        Returns True if found anywhere. Early terminates only if first key matches but structure is incomplete.
        """
        first_key = next(iter(searched_structure))

        if first_key in data_frame:
            return self._validates_partial_structure_match(data_frame=data_frame, searched_structure=searched_structure)

        for data in data_frame.values():
            if isinstance(data, dict):
                if self._contains_structure_pattern(data_frame=data, searched_structure=searched_structure):
                    return True

        return False

    def _validates_partial_structure_match(self, data_frame: dict[str, Any],
                                           searched_structure: dict[str, Any]) -> bool:
        """
        Validates if the searched_structure keys are present and match their expected values.
        The data_frame can contain additional fields beyond those in searched_structure.
        """
        for expected_key, expected_value in searched_structure.items():
            if expected_key not in data_frame:
                return False

            if isinstance(expected_value, dict):
                if not isinstance(data_frame[expected_key], dict):
                    return False
                if not self._validates_partial_structure_match(
                        data_frame=data_frame[expected_key],
                        searched_structure=expected_value):
                    return False
            else:
                if data_frame[expected_key] != expected_value:
                    return False

        return True

    def _get_bts_node(self):
        """
        Gets BTS node type based on testline init configuration.
        :return: 'gnb' or 'enb' string
        :rtype: str
        """
        gnbs = BuiltIn().get_variable_value("${tl.gnbs}")
        return "gnb" if gnbs else "enb"


class VerifyPcapNSA(VerifyPcap):
    def __init__(self, ran, cell_distname):
        super(VerifyPcapNSA, self).__init__(ran, cell_distname)
        if "NRCELL" in cell_distname:
            self._ok_msgs = {
                'SNStatusTransfer': 4
            }
            self._nok_msgs = {
                'sgNBinitiatedSgNBRelease': 32,
                'UEContextReleaseComplete': 5
            }
            self._protocol = "x2ap"
            self._nok_structures = []
        else:
            self._protocol = self._cell.get_protocol_for_pcap_verification()
            self._ok_msgs = self._cell.get_ok_msgs_and_procedure_codes()
            self._nok_msgs = self._cell.get_nok_msgs_and_procedure_codes()
            self._nok_structures = self._cell.get_nok_structures()
